<div class="dashboard"><aside class="sidebar"><div class="sidebar-logo">Site<span>Match</span></div><div class="sidebar-user"><strong><?= eDevBusca((string)($usuario['nome']??'')) ?></strong><span>Cliente</span></div><nav class="sidebar-nav"><ul><li><a href="dashboard.php">Início</a></li><li><a href="meus-projetos.php">Meus projetos</a></li><li><a href="projetos-contratados.php">Contratações</a></li><li><a class="ativo" href="desenvolvedores.php">Desenvolvedores</a></li><li><a href="/mensagens.php">Mensagens</a></li><li><a href="/historico.php">Histórico</a></li><li><a href="/perfil.php">Meu perfil</a></li><li class="menu-sair"><a href="../logout.php">Sair</a></li></ul></nav></aside>
<main class="dashboard-main"><header class="dashboard-header"><div class="dashboard-header-text"><h1>Encontrar desenvolvedores</h1><p>Pesquise profissionais por nome, experiência, habilidade ou faixa de preço.</p></div></header>
<form method="GET" class="form-card filtros"><div class="form-campo"><label for="q">Nome ou experiência</label><input id="q" name="q" value="<?= eDevBusca((string)$filtros['q']) ?>"></div><div class="form-campo"><label for="habilidade">Habilidade</label><input id="habilidade" name="habilidade" value="<?= eDevBusca((string)$filtros['habilidade']) ?>" placeholder="PHP, JavaScript..."></div><div class="form-campo"><label for="preco_max">Preço máximo</label><input id="preco_max" name="preco_max" type="number" min="0" step="0.01" value="<?= eDevBusca((string)$filtros['preco_max']) ?>"></div><div class="form-acoes"><button class="botao-principal">Pesquisar</button><a class="botao-secundario" href="desenvolvedores.php">Limpar</a></div></form>
<section class="dashboard-section"><h2><?= count($desenvolvedores) ?> profissional(is)</h2><?php if(empty($desenvolvedores)): ?><div class="projetos-vazio">Nenhum desenvolvedor encontrado.</div><?php else: ?><div class="lista-simples"><?php foreach($desenvolvedores as $d): ?><article class="projeto-card"><div class="projeto-card-topo"><div><h3><?= eDevBusca((string)$d['nome']) ?></h3><p style="margin-top:5px;"><?= eDevBusca((string)($d['titulo_profissional']?:'Perfil profissional em construção')) ?></p></div><?php if((int)$d['total_avaliacoes']>0): ?><span class="projeto-status">★ <?= eDevBusca((string)$d['media_avaliacoes']) ?> (<?= (int)$d['total_avaliacoes'] ?>)</span><?php endif; ?></div><?php if(!empty($d['bio'])): ?><p style="margin-top:14px;line-height:1.5;"><?= eDevBusca((string)$d['bio']) ?></p><?php endif; ?><?php if(!empty($d['habilidades'])): ?><div class="tags"><?php foreach(explode(', ',(string)$d['habilidades']) as $h): ?><span class="tag"><?= eDevBusca($h) ?></span><?php endforeach; ?></div><?php endif; ?><div class="projeto-meta" style="margin-top:16px;"><?php if($d['faixa_preco_min']!==null): ?><span>Faixa: <strong><?= dinheiroDevBusca((float)$d['faixa_preco_min']) ?><?= $d['faixa_preco_max']!==null?' a '.dinheiroDevBusca((float)$d['faixa_preco_max']):'' ?></strong></span><?php endif; ?><span>Disponibilidade: <strong><?= eDevBusca((string)($d['disponibilidade']??'Não informada')) ?></strong></span></div><div class="acoes-inline"><a class="botao-principal" href="/desenvolvedor-publico.php?id=<?= (int)$d['desenvolvedor_id'] ?>">Ver perfil</a></div></article><?php endforeach; ?></div><?php endif; ?></section>
